<?php

declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
use EventMenu\Core\Database;
use EventMenu\Core\Security;
$pdo=Database::connection();$slug=trim((string)($_GET['evento']??''));$s=$pdo->prepare('SELECT e.*,t.name tenant_name FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$slug]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Evento não encontrado.');}$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? AND active=1 ORDER BY id');$b->execute([$event['id']]);$batches=$b->fetchAll();function emoney(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= Security::e($event['name']) ?> — EventMenu</title><link rel="stylesheet" href="assets/app.css"><style>.event-shell{max-width:980px;margin:auto;padding:32px 18px}.event-hero{padding:38px;border-radius:28px;background:linear-gradient(135deg,#181e2b,#11151c);border:1px solid var(--line)}.event-hero h1{font-size:clamp(34px,7vw,72px);line-height:.95;margin:20px 0}.ticket-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}@media(max-width:760px){.ticket-grid{grid-template-columns:1fr}}</style></head><body><main class="event-shell"><section class="event-hero"><div class="brand">EventMenu <span>Premium</span></div><p class="muted"><?= Security::e($event['tenant_name']) ?></p><h1><?= Security::e($event['name']) ?></h1><p><?= nl2br(Security::e($event['description'])) ?></p><p><strong><?= Security::e(date('d/m/Y H:i',strtotime($event['starts_at']))) ?></strong><br><?= Security::e($event['venue']) ?><br><span class="muted"><?= Security::e($event['address']) ?></span></p></section><section style="margin-top:24px"><div class="section-head"><h2>Ingressos</h2></div><div class="ticket-grid"><?php foreach($batches as $batch):$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']);?><article class="card"><span class="badge"><?= Security::e($batch['name']) ?></span><h2><?= emoney((int)$batch['price_cents']) ?></h2><p class="muted"><?= $available ?> disponíveis</p><?php if($available>0):?><button class="primary" disabled>Venda online será liberada pelo gateway</button><?php else:?><span class="badge">Esgotado</span><?php endif;?></article><?php endforeach;?></div></section></main></body></html>
